public static class SpatialProbe {static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;public static object Run(){Physics.SyncTransforms();return new[]{new Vector3(-22,-82,21),new Vector3(-22,-82,22.7f),new Vector3(-24.1f,-82,15.3f),new Vector3(-23.2f,-82,16.2f),new Vector3(17,-82,-1.9f)}.Select(p=>new{point=p.ToString(),colliders=Physics.OverlapCapsule(p+Vector3.up*.49f,p+Vector3.up*1.59f,.38f,~0,QueryTriggerInteraction.Ignore).Select(c=>new{path=P(c.transform),type=c.GetType().Name,bounds=c.bounds.ToString()})}).ToArray();}}
